F1b = [['zone a', '4 个 Pod'], ['zone b', '1 个 Pod'], ['zone c', '1 个 Pod']]
F2 = [['zone a', '4(强行放的)'], ['zone b', '0 → 1'], ['zone c', '0 → 2']]
